using System;using System.IO;using System.Linq;using System.Web;using System.Web.Mvc;using FindIt.DAL;using FindIt.Models;namespace FindIt.Controllers{public class ItemController:Controller{ItemRepository repo=new ItemRepository();int U=>Session["UserId"]==null?0:(int)Session["UserId"];bool Student=>Session["Role"] as string=="Student"&&U>0;public ActionResult Index(string q,string category,string type,string location,DateTime? date){ViewBag.Q=q;ViewBag.Category=category;ViewBag.Type=type;ViewBag.Location=location;ViewBag.Date=date;return View(repo.Search(q,category,type,location,date));}public ActionResult Details(int id){var i=repo.Get(id);return i==null?(ActionResult)HttpNotFound():View(i);}[HttpGet]public ActionResult Create(string type="Lost"){if(!Student)return RedirectToAction("Login","Account");return View(new Item{ItemType=type,DateOfIncident=DateTime.Today});}[HttpPost,ValidateAntiForgeryToken]public ActionResult Create(Item m,HttpPostedFileBase image){if(!Student)return RedirectToAction("Login","Account");if(!new[]{"Lost","Found"}.Contains(m.ItemType)||!new[]{"Electronics","Books","ID/Card","Keys","Clothing","Accessories","Other"}.Contains(m.Category)){ModelState.AddModelError("","Choose valid item type and category.");}if(m.DateOfIncident>DateTime.Today){ModelState.AddModelError("DateOfIncident","Incident date cannot be in the future.");}string path=null;if(image!=null&&image.ContentLength>0){path=Upload(image);if(path==null)ModelState.AddModelError("","Image must be JPG, PNG or WEBP and up to 5MB.");}if(!ModelState.IsValid)return View(m);m.UserId=U;m.ImagePath=path;try{repo.Save(m);TempData["Message"]="Report posted.";return RedirectToAction("Index");}catch{ModelState.AddModelError("","Could not save report.");return View(m);}}[HttpGet]public ActionResult Edit(int id){if(!Student)return RedirectToAction("Login","Account");var m=repo.Get(id);if(m==null||m.UserId!=U)return HttpNotFound();return View(m);}[HttpPost,ValidateAntiForgeryToken]public ActionResult Edit(Item m,HttpPostedFileBase image){if(!Student)return RedirectToAction("Login","Account");var existing=repo.Get(m.ItemId);if(existing==null||existing.UserId!=U)return HttpNotFound();if(image!=null&&image.ContentLength>0){var p=Upload(image);if(p==null)ModelState.AddModelError("","Invalid image upload.");else m.ImagePath=p;}m.UserId=U;if(!ModelState.IsValid)return View(m);repo.Save(m);return RedirectToAction("MyReports","Student");}[HttpPost,ValidateAntiForgeryToken]public ActionResult Delete(int id){if(!Student)return RedirectToAction("Login","Account");repo.Delete(id,U);return RedirectToAction("MyReports","Student");}private string Upload(HttpPostedFileBase f){if(f.ContentLength>5242880)return null;string ext=Path.GetExtension(f.FileName).ToLowerInvariant();if(!new[]{".jpg",".jpeg",".png",".webp"}.Contains(ext))return null;byte[] b=new byte[12];int read=f.InputStream.Read(b,0,b.Length);f.InputStream.Position=0;bool valid=(ext==".jpg"||ext==".jpeg")&&read>=2&&b[0]==255&&b[1]==216||(ext==".png"&&read>=8&&b[0]==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)||(ext==".webp"&&read>=12&&b[0]==82&&b[1]==73&&b[2]==70&&b[3]==70&&b[8]==87&&b[9]==69&&b[10]==66&&b[11]==80);if(!valid)return null;var name=Guid.NewGuid().ToString("N")+ext;var dir=Server.MapPath("~/Uploads");Directory.CreateDirectory(dir);f.SaveAs(Path.Combine(dir,name));return "/Uploads/"+name;}}}